<script setup lang="ts">
import {operationDescription} from './operationPresentation'
import {computed,ref,onMounted,onBeforeUnmount,nextTick} from 'vue'
import AgentIcon from '@/components/assistant/AgentIcon.vue'
import {visionList,type VisionRecord} from '@/api/vision'
import {fetchOperations,createOperation,type OperationRecord} from '@/api/dashboard'
import type {DashboardSnapshot,SceneEntity} from '@/types'
const props=defineProps<{snapshot:DashboardSnapshot;entity?:SceneEntity}>()
const emit=defineEmits<{(e:'close'):void;(e:'ask',question:string):void}>()
const tabs=[{id:'overview',label:'风险总览'},{id:'production',label:'生产风险'},{id:'postharvest',label:'采后风险'},{id:'evidence',label:'因果与证据'},{id:'simulation',label:'方案推演'},{id:'history',label:'历史记录'}]
const tab=ref('overview'),selected=ref(props.snapshot.zones.some(z=>z.entityId===props.entity?.id)?props.entity!.id:props.snapshot.zones[0]?.entityId||'')
const records=ref<VisionRecord[]>([]),operations=ref<OperationRecord[]>([]),error=ref(''),loading=ref(true),saving=ref(false),notice=ref(''),panel=ref<HTMLElement>()
const ventilation=ref(true),review=ref(true),sorting=ref(true)
const name=(id:string)=>props.snapshot.entities.find(e=>e.id===id)?.name||id
const zone=computed(()=>props.snapshot.zones.find(z=>z.entityId===selected.value))
const moisture=computed(()=>props.snapshot.environmentMetrics.find(m=>m.label.includes('土壤湿度')))
const humidity=computed(()=>props.snapshot.environmentMetrics.find(m=>m.label==='空气湿度'))
const activeAlerts=computed(()=>props.snapshot.alerts.filter(a=>!['已处理','已恢复'].includes(a.status)))
const assessments=computed(()=>props.snapshot.zones.map(z=>{
 const alerts=activeAlerts.value.filter(a=>a.entityId===z.entityId)
 const visual=records.value.filter(r=>r.plotId===z.entityId&&r.result).sort((a,b)=>b.createdAt.localeCompare(a.createdAt))[0]
 const candidates=visual?.result?.detections.length||0
 const score=Math.min(100,20+alerts.length*20+(candidates?25:0))
 return {id:z.entityId,name:name(z.entityId),score,alerts,visual,candidates}
}))
const current=computed(()=>assessments.value.find(a=>a.id===selected.value))
const level=(score:number)=>score>=65?'高关注':score>=40?'中关注':'低关注'
const average=computed(()=>Math.round(assessments.value.reduce((s,a)=>s+a.score,0)/Math.max(1,assessments.value.length)))
const batches=computed(()=>operations.value.filter(r=>r.kind==='BATCH'&&r.entityId===selected.value))
const actions=computed(()=>[{name:'核查视觉候选',enabled:review.value,weight:8},{name:'核查通风与水分条件',enabled:ventilation.value,weight:5},{name:'分选及贮藏条件核验',enabled:sorting.value,weight:7}])
const simulated=computed(()=>Math.max(0,(current.value?.score||20)-actions.value.filter(a=>a.enabled).reduce((s,a)=>s+a.weight,0)))
const ruleDescription='演示关注指数：基础20 + 每条未处理地块告警20 + 存在视觉候选25，上限100；不是病害概率。'
async function reload(){loading.value=true;error.value='';try{const results=await Promise.allSettled([visionList(props.snapshot.farmId),fetchOperations(props.snapshot.farmId)]);if(results[0].status==='fulfilled')records.value=results[0].value;else error.value='视觉记录加载失败，相关评估暂不完整。';if(results[1].status==='fulfilled')operations.value=results[1].value;else error.value+=' 农事记录加载失败，请重试。'}finally{loading.value=false}}
function analyze(){emit('ask',`针对${name(selected.value)}进行生产与采后风险评估，读取观测、视觉和业务记录，检索作物资料，区分相关与因果；不得将演示关注指数当作疾病概率。`)}
async function save(){if(saving.value)return;saving.value=true;notice.value='';try{await createOperation({kind:'AGRONOMY',entityId:selected.value,title:'风险评估 · 演示方案记录',detail:JSON.stringify({rule:ruleDescription,snapshot:props.snapshot.generatedAt,current:current.value?.score,simulated:simulated.value,actions:actions.value.filter(a=>a.enabled).map(a=>a.name),limitation:'固定权重界面推演，不是模型预测；未执行设备操作。'})},props.snapshot.farmId);notice.value='方案已保存为农事记录，未执行设备操作。';await reload()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
function download(){const url=URL.createObjectURL(new Blob([JSON.stringify({snapshot:props.snapshot.generatedAt,rule:ruleDescription,assessment:current.value,batches:batches.value},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='盐田丰语-风险评估.json';a.click();URL.revokeObjectURL(url)}
const previous=document.activeElement as HTMLElement|null
function key(event:KeyboardEvent){if(event.key==='Escape'){emit('close');return}if(event.key!=='Tab')return;const list=Array.from(panel.value?.querySelectorAll<HTMLElement>('button:not([disabled]),select,input,a[href]')||[]).filter(e=>e.offsetParent!==null);const first=list[0],last=list[list.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}
onMounted(async()=>{await nextTick();panel.value?.focus();reload()});onBeforeUnmount(()=>previous?.isConnected&&previous.focus())
</script>
<template><Teleport to="body"><div class="risk-backdrop" @click.self="emit('close')"><section ref="panel" class="risk-center" role="dialog" aria-modal="true" aria-label="AI 风险决策中心" tabindex="-1" @keydown="key"><header><div><small>盐田丰语 · 农业决策工作空间</small><h1>AI 风险决策中心 <span>软件演示</span></h1></div><button aria-label="关闭风险评估" @click="emit('close')"><AgentIcon name="close" :size="20"/></button></header><div class="risk-layout"><aside><div class="risk-brand"><AgentIcon name="leaf" :size="23"/><span>从观测到决策<small>生产 · 采后 · 证据</small></span></div><nav aria-label="风险评估页面"><button v-for="item in tabs" :key="item.id" :aria-pressed="tab===item.id" :class="{active:tab===item.id}" @click="tab=item.id"><AgentIcon :name="item.id==='history'?'clock':item.id==='evidence'?'book':'leaf'" :size="17"/>{{item.label}}<span>›</span></button></nav><div class="sidebar-foot">演示数据与评估记录<br/>不执行设备控制</div></aside><main><div class="risk-heading"><div><small>{{tabs.find(t=>t.id===tab)?.label}}</small><h2>{{tab==='overview'?'看清风险，逐步核验':name(selected)}}</h2></div><div class="risk-controls"><select v-model="selected" aria-label="风险评估地块"><option v-for="z in snapshot.zones" :key="z.entityId" :value="z.entityId">{{name(z.entityId)}}</option></select><button :disabled="loading" @click="reload">{{loading?'同步中…':'刷新记录'}}</button></div></div><p v-if="error" role="alert" class="risk-error">{{error}}</p><p v-if="notice" role="status" class="risk-notice">{{notice}}</p>
<template v-if="tab==='overview'"><div class="risk-stats"><div><small>综合关注指数</small><strong>{{average}}<em>/ 100</em></strong><span>{{level(average)}} · 演示规则</span></div><div v-for="range in [{label:'高关注地块',min:65,max:101},{label:'中关注地块',min:40,max:65},{label:'低关注地块',min:0,max:40}]" :key="range.label"><small>{{range.label}}</small><strong>{{assessments.filter(a=>a.score>=range.min&&a.score<range.max).length}}<em>块</em></strong><span>当前地块档案</span></div></div><div class="risk-columns"><section class="risk-card"><h3>地块风险分布</h3><div class="plot-grid"><button v-for="a in assessments" :key="a.id" :class="{selected:selected===a.id}" @click="selected=a.id;tab='production'"><AgentIcon name="leaf" :size="23"/><strong>{{a.name}}</strong><span>{{a.score}} · {{level(a.score)}}</span></button></div><p class="caption">地块卡片展示规则评估，不代表真实风险地图。</p></section><section class="risk-card"><h3>重点核验对象</h3><button v-for="a in [...assessments].sort((a,b)=>b.score-a.score).slice(0,4)" :key="a.id" class="risk-row" @click="selected=a.id;tab='production'"><div><strong>{{a.name}}</strong><small>{{a.alerts.length}} 条未处理告警 · {{a.candidates}} 个视觉候选</small></div><span>{{level(a.score)}} ↗</span></button><button class="text-button" @click="analyze">交给 Agent 综合分析 →</button></section></div></template>
<template v-else-if="tab==='production'"><div class="detail-banner"><div><small>{{zone?.crop}} · {{zone?.stage}}</small><h3>生产风险 → 采后核验</h3><p>现有观测、视觉候选和异常记录分别列出。</p></div><div class="score-ring"><strong>{{current?.score||20}}</strong><small>{{level(current?.score||20)}}</small></div></div><div class="risk-columns"><section class="risk-card"><h3>多模态感知数据</h3><div class="observation-cards"><article><small>视觉识别</small><strong>{{current?.visual?current.candidates+' 个候选':'尚无检测记录'}}</strong><p>{{current?.visual?.filename||'请在作物侧栏采集叶片图像'}}</p></article><article><small>环境观测 · 农场级</small><strong>{{humidity?.numericValue??'—'}}% 空气湿度</strong><p>{{moisture?.numericValue??'—'}}% 土壤湿度</p></article><article><small>地块异常</small><strong>{{current?.alerts.length||0}} 条待处理</strong><p>{{current?.alerts.map(a=>a.title).join('；')||'当前没有未处理告警'}}</p></article></div><button class="text-button" @click="tab='evidence'">查看因果与证据 →</button></section><section class="risk-card"><h3>建议核验路径</h3><ol class="steps"><li>确认叶片图像与人工复核结果</li><li>对照配置阈值检查观测异常</li><li>检索该作物生产与采后资料</li><li>形成可追溯的农事方案</li></ol><button class="primary" @click="analyze">Agent 分析现有证据 ↗</button><button class="secondary" @click="tab='simulation'">进入干预方案推演</button></section></div></template>
<template v-else-if="tab==='postharvest'"><section class="risk-card"><h3>采后批次与风险核验</h3><p class="caption">检查采收、分选、贮藏和出库记录；没有批次时不推断损失率。</p><article v-for="batch in batches" :key="batch.id" class="history-row"><strong>{{batch.title}}</strong><span>{{batch.quantity}} {{batch.unit}} · {{batch.stage}}</span><p>{{batch.detail}}</p><time>{{batch.createdAt}}</time></article><div v-if="!batches.length" class="empty">该地块尚无采后批次，先在作物中心登记采收记录。</div><button class="primary" @click="analyze">检索生产与采后联动资料 ↗</button></section></template>
<template v-else-if="tab==='evidence'"><section class="risk-card"><h3>风险来源与证据链</h3><div class="chain"><span>农场环境观测</span><b>→</b><span>地块异常记录</span><b>→</b><span>视觉候选复核</span><b>→</b><span>生产与采后建议</span></div><p class="caption">这是核验工作流程，尚不构成经验证的因果模型。</p><div class="observation-cards"><article><small>环境来源</small><strong>{{snapshot.environmentMetrics.length}} 项观测</strong><p>{{snapshot.generatedAt}} · {{snapshot.virtualData?'共享演示数据':'业务快照'}}</p></article><article><small>视觉来源</small><strong>{{current?.visual?.result?.modelId||'暂无结果'}}</strong><p>{{current?.visual?.createdAt||'等待图像采集'}}</p></article><article><small>业务来源</small><strong>{{operations.filter(r=>r.entityId===selected).length}} 条记录</strong><p>农事、生长及采后批次</p></article></div><button class="primary" @click="analyze">进入 Agent 检索与证据核验 ↗</button><button class="text-button" @click="download">导出当前评估依据 →</button></section></template>
<template v-else-if="tab==='simulation'"><section class="detail-banner"><div><small>干预方案推演 · 固定权重模拟</small><h3>比较核验方案</h3><p>调整核验措施，观察界面演示指数的变化。</p></div><div class="simulation-score"><strong>{{current?.score||20}}</strong><span>→</span><strong>{{simulated}}</strong><small>演示指数</small></div></section><div class="plan-grid"><section class="risk-card"><h3>方案 A · 保持现状</h3><strong class="plan-score">{{current?.score||20}}</strong><p class="caption">尚未新增核验措施</p></section><section class="risk-card"><h3>方案 B · 单项核验</h3><strong class="plan-score">{{Math.max(0,(current?.score||20)-8)}}</strong><p class="caption">核查视觉候选 · 演示减 8</p></section><section class="risk-card recommended"><h3>方案 C · 组合核验</h3><strong class="plan-score">{{simulated}}</strong><label><input v-model="review" type="checkbox"/>核查视觉候选 <small>−8</small></label><label><input v-model="ventilation" type="checkbox"/>核查通风与水分条件 <small>−5</small></label><label><input v-model="sorting" type="checkbox"/>分选及贮藏条件核验 <small>−7</small></label><button class="primary" :disabled="saving||loading" @click="save">{{saving?'保存中…':'保存方案为农事记录'}}</button></section></div><p class="caption">上述权重仅用于软件交互演示，没有校准为真实干预效果或风险降低概率。</p></template>
<template v-else><section class="risk-card"><h3>评估与农事历史</h3><article v-for="record in operations.filter(r=>r.entityId===selected)" :key="record.id" class="history-row"><strong>{{record.title}}</strong><span>{{record.kind}} · {{record.simulated?'演示记录':'业务记录'}}</span><p>{{operationDescription(record.detail)}}</p><time>{{record.createdAt}}</time></article><div v-if="!operations.some(r=>r.entityId===selected)" class="empty">暂无记录，保存方案后可在这里追溯。</div></section></template>
<p class="rule-note">{{ruleDescription}} 快照 {{snapshot.generatedAt}}</p></main></div></section></div></Teleport></template>
<style scoped>
.risk-backdrop{position:fixed;inset:0;z-index:140;background:#0e1b29aa;backdrop-filter:blur(12px);display:grid;place-items:center;padding:24px}.risk-center{width:min(1200px,100%);height:min(860px,92vh);background:var(--ui-subtle);color:var(--ui-ink);border:1px solid #fff8;border-radius:22px;box-shadow:0 30px 100px #0005;display:flex;flex-direction:column;overflow:hidden;font-family:var(--font-sans);animation:appear .25s ease}button,select,input{font:inherit}button{cursor:pointer;color:inherit}button:disabled{opacity:.5;cursor:wait}button:focus-visible,select:focus-visible,input:focus-visible{outline:2px solid var(--ui-brand);outline-offset:3px}header{display:flex;align-items:center;justify-content:space-between;padding:22px 28px;border-bottom:1px solid var(--ui-brand-soft)}header small{font-size:10px;color:#8b999f}h1{font-size:22px;margin:6px 0 0;font-weight:650}h1 span{font-size:10px;font-weight:400;color:var(--ui-brand);background:var(--ui-brand-soft);padding:5px 8px;border-radius:6px;margin-left:8px}header>button{display:grid;place-items:center;width:34px;height:34px;border:0;border-radius:9px;background:var(--ui-brand-soft)}.risk-layout{display:grid;grid-template-columns:210px minmax(0,1fr);flex:1;min-height:0}aside{padding:24px 15px;border-right:1px solid var(--ui-brand-soft);display:flex;flex-direction:column;background:#f5f9f6}.risk-brand{display:flex;gap:10px;align-items:center;color:var(--ui-brand);padding:0 8px 24px;font-size:12px}.risk-brand small{display:block;color:#95a49b;font-size:10px;margin-top:5px}nav{display:grid;gap:7px}nav button{display:flex;align-items:center;gap:11px;width:100%;padding:13px 12px;border:0;border-radius:10px;background:transparent;text-align:left;font-size:12px;color:#73887d;transition:.2s}nav button span{margin-left:auto}nav button:hover{background:var(--ui-brand-soft)}nav button.active{background:var(--ui-brand);color:white;box-shadow:0 5px 15px #28664820}.sidebar-foot{margin-top:auto;font-size:10px;line-height:1.9;color:#a0a